using System; namespace Reflectable { public sealed class ExperienceManager { public int Level{get;private set;}=1; public int Experience{get;private set;} public int SkillPoints{get;private set;} public int Required=>25+Level*15; public event Action Leveled; public void Add(int n){Experience+=n;while(Experience>=Required){Experience-=Required;Level++;SkillPoints++;Leveled?.Invoke();}} public bool Spend(int n){if(SkillPoints<n)return false;SkillPoints-=n;return true;} } }
